document.addEventListener("DOMContentLoaded",function(){const t=document.querySelector(".reportPost");t&&t.addEventListener("click",function(t){const o=window.location.href,e=document.querySelector(".items_postTitle"),n={url:o,title:e?e.innerText.trim():"Không tìm thấy Tiêu đề"};try{localStorage.setItem("reportedPostData",JSON.stringify(n)),window.location.href="https://www.vutruong.vn/p/report.html"}catch(t){console.error("Lỗi khi lưu dữ liệu vào localStorage:",t),window.location.href="https://www.vutruong.vn/p/report.html"}})});